#!/usr/bin/env node
/**
 * Refresh the frozen baseline artifacts.
 *
 *   node tests/fixtures/update-pre-migration.mjs
 *
 * Two things are frozen here, for different reasons:
 *
 *   pre-migration-values.json  — every brand value as it existed in the wild
 *     before press generated any of it. This is the migration's no-op proof and
 *     should almost never be regenerated: rewriting it to match a change is how
 *     you would erase the evidence that the change broke a shipped product.
 *     Regenerate ONLY when adding a newly-discovered pre-existing source.
 *
 *   golden/<target>.txt        — the exact bytes each target's region should
 *     contain. The region *is* the contract, so byte-exactness is right here
 *     (the same call shipflow makes for its rendered workflow). Regenerate
 *     whenever an emitter or a token deliberately changes, and read the diff.
 */
import { writeFileSync, mkdirSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

import { loadTokens } from '../../lib/tokens.mjs';
import { emitBody } from '../../lib/emit.mjs';
import { loadTargets } from '../../lib/targets.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
const GOLDEN = join(HERE, 'golden');

const tokens = loadTokens();
const targets = loadTargets();

mkdirSync(GOLDEN, { recursive: true });
for (const target of targets) {
  const body = emitBody(tokens, target.emitter, target.params ?? {});
  writeFileSync(join(GOLDEN, `${target.id}.txt`), `${body}\n`, 'utf8');
}

const manifest = {
  $comment:
    'Byte-exact expected region body per target. Regenerated by update-pre-migration.mjs; read the diff before committing.',
  min_targets: 8,
  targets: targets.map((t) => t.id),
};
writeFileSync(join(GOLDEN, 'manifest.json'), `${JSON.stringify(manifest, null, 2)}\n`, 'utf8');

process.stdout.write(`wrote ${targets.length} goldens to tests/fixtures/golden/\n`);
process.stdout.write(
  `pre-migration-values.json left untouched (${
    Object.keys(JSON.parse(readFileSync(join(HERE, 'pre-migration-values.json'), 'utf8')).sources).length
  } sources) — edit it by hand only, and say why.\n`,
);
